/**
 * Oczekuje JSON body: { source?, payload_json, ai_json? }
 * payload_json = pełny obiekt z ParseAndRoute + pola maila (jak w automail).
 * Nagłówek: Authorization: Bearer <HITL_WEBHOOK_SECRET>
 */
function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}
const item = $input.first().json;
const headers = item.headers || {};
const auth = String(headers.authorization || headers.Authorization || '').trim();
let secret = '';
try { secret = String($env.HITL_WEBHOOK_SECRET || '').trim(); } catch (e) {}
if (!secret || auth !== 'Bearer ' + secret) {
  return [{ json: { unauthorized: true } }];
}
const body = item.body;
if (!body || typeof body !== 'object') {
  return [{ json: { unauthorized: true, bad_body: true } }];
}
const source = String(body.source || 'mail');
const payload_json = body.payload_json != null ? body.payload_json : body;
const ai_json = body.ai_json != null ? body.ai_json : null;
let chatId = '';
try { chatId = String($env.TELEGRAM_OPERATOR_CHAT_ID || '').trim(); } catch (e) {}
if (!chatId) throw new Error('Ustaw TELEGRAM_OPERATOR_CHAT_ID (env)');
const lead_id = uuidv4();
const subj = String(payload_json.emailSubject || '').slice(0, 100);
const from = String(payload_json.emailFrom || payload_json.client_to_email || '').slice(0, 80);
const text =
  'Nowe zapytanie (HITL) — zatwierdz wysylke\n\n' +
  'ID: ' + lead_id + '\n' +
  'Zrodlo: ' + source + '\n' +
  'Temat: ' + subj + '\n' +
  'Od: ' + from + '\n\n' +
  'Akceptuj / Odrzuc — przyciski ponizej.';
return [{
  json: {
    unauthorized: false,
    lead_id,
    source,
    payload_json,
    ai_json,
    chatId,
    telegram_text: text,
    callback_approve: 'ap:' + lead_id,
    callback_reject: 'rj:' + lead_id,
  },
}];
